#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "correlation.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension descriptors
constexpr auto r_vec = noarr::vector<'r'>(); // row index (0..N-1)
constexpr auto c_vec = noarr::vector<'c'>(); // column index (0..M-1)
constexpr auto i_vec = noarr::vector<'i'>(); // corr row index (0..M-1)
constexpr auto j_vec = noarr::vector<'j'>(); // corr column index (0..M-1)

struct tuning {
	// data: N x M   -> dims: r (rows), c (cols), contiguous in 'c'
	DEFINE_PROTO_STRUCT(data_layout, c_vec ^ r_vec);

	// corr: M x M   -> dims: i (rows), j (cols), contiguous in 'j'
	DEFINE_PROTO_STRUCT(corr_layout, j_vec ^ i_vec);

	// 1D vectors (mean, stddev): length M, dim: c
	DEFINE_PROTO_STRUCT(vec_layout, c_vec);
} tuning;

// initialization function
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// number of rows (N)
	auto n_rows = data | get_length<'r'>();
	// number of columns (M)
	auto n_cols = data | get_length<'c'>();

	float_n = static_cast<num_t>(n_rows);

	traverser(data).for_each([=](auto state) {
		auto [r, c] = get_indices<'r', 'c'>(state);

		data[state] = static_cast<num_t>(r * c) / static_cast<num_t>(n_cols)
			+ static_cast<num_t>(r);
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	num_t eps = static_cast<num_t>(0.1);

	#pragma scop
	// -----------------------------------------------------------------
	// Step 1: compute the mean of each column:
	// mean[j] = sum_i data[i][j] / float_n
	// -----------------------------------------------------------------
	traverser(data, mean).template for_dims<'c'>([=](auto trav_c) {
		// trav_c has column 'c' fixed, remaining dim: 'r'
		auto s_c = trav_c.state(); // contains 'c'

		mean[s_c] = static_cast<num_t>(0.0);

		trav_c.for_each([=](auto state) {
			// state has 'r' and 'c'; mean only uses 'c'
			mean[s_c] += data[state];
		});

		mean[s_c] /= float_n;
	});

	// -----------------------------------------------------------------
	// Step 2: compute the standard deviation of each column:
	// stddev[j] = sqrt( sum_i (data[i][j] - mean[j])^2 / float_n )
	// with protection against near-zero stddev
	// -----------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'c'>([=](auto trav_c) {
		auto s_c = trav_c.state(); // contains 'c'

		stddev[s_c] = static_cast<num_t>(0.0);

		trav_c.for_each([=](auto state) {
			num_t diff = data[state] - mean[s_c];
			stddev[s_c] += diff * diff;
		});

		stddev[s_c] /= float_n;
		stddev[s_c] = std::sqrt(stddev[s_c]);

		// avoid division by (almost) zero
		stddev[s_c] = stddev[s_c] <= eps ? static_cast<num_t>(1.0) : stddev[s_c];
	});

	// -----------------------------------------------------------------
	// Step 3: center and reduce the data:
	// data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	// -----------------------------------------------------------------
	num_t sqrt_float_n = std::sqrt(float_n);

	traverser(data, mean, stddev).for_each([=](auto state) {
		// state has 'r' and 'c'
		num_t &d = data[state];
		num_t m_col = mean[state];   // uses 'c' from state
		num_t sd_col = stddev[state]; // uses 'c' from state

		d -= m_col;
		d /= sqrt_float_n * sd_col;
	});

	// -----------------------------------------------------------------
	// Step 4: compute the correlation matrix:
	//
	// for i in [0, M):
	//   corr[i][i] = 1
	//   for j in (i, M):
	//     corr[i][j] = sum_k data[k][i] * data[k][j]
	//     corr[j][i] = corr[i][j]
	//
	// We traverse the full i x j space and only compute when j >= i.
	// -----------------------------------------------------------------
	traverser(corr).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed, remaining dim: 'j'
		trav_i.for_each([=](auto state_ij) {
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(state_ij);

			if (i_idx == j_idx) {
				// diagonal
				corr[state_ij] = static_cast<num_t>(1.0);
			} else if (j_idx > i_idx) {
				// upper triangle: compute correlation and mirror it
				num_t sum = static_cast<num_t>(0.0);

				// sum over rows 'r'
				traverser(data).template for_dims<'r'>([&](auto trav_r) {
					auto s_r = trav_r.state();
					auto r_idx = get_index<'r'>(s_r);

					sum += data[noarr::idx<'r', 'c'>(r_idx, i_idx)]
						* data[noarr::idx<'r', 'c'>(r_idx, j_idx)];
				});

				corr[state_ij] = sum;
				corr[noarr::idx<'i', 'j'>(j_idx, i_idx)] = sum; // symmetric entry
			}
			// for j_idx < i_idx: already set when the pair (j_idx, i_idx) was processed
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N; // number of rows
	std::size_t m = M; // number of columns / variables

	// input data
	num_t float_n;

	// set lengths for individual structures
	auto set_lengths_data = noarr::set_length<'r'>(n) ^ noarr::set_length<'c'>(m);
	auto set_lengths_corr = noarr::set_length<'i'>(m) ^ noarr::set_length<'j'>(m);
	auto set_lengths_vec  = noarr::set_length<'c'>(m);

	// allocate bags
	auto data   = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths_data);
	auto corr   = noarr::bag(noarr::scalar<num_t>() ^ tuning.corr_layout ^ set_lengths_corr);
	auto mean   = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths_vec);
	auto stddev = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths_vec);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_correlation(float_n, data.get_ref(), corr.get_ref(), mean.get_ref(), stddev.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to stderr) if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' so rows are printed consecutively
		noarr::serialize_data(std::cerr, corr.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing (to stdout)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
