		auto col_state = col_trav.state(); // contains 'c'

		mean[col_state] = SCALAR_VAL(0.0);

		col_trav.for_each([=](auto state) {
			// state has 'r' and 'c'
			mean[state] += data[state];
		});

		mean[col_state] /= float_n;
	});

