	// stddev[j] = sqrt( sum_i (data[i][j] - mean[j])^2 / float_n )
	// with safeguard for near-zero stddev
	// --------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'c'>([=](auto col_trav) {
		auto col_state = col_trav.state(); // contains 'c'

