		col_trav.for_each([=](auto state) {
			auto diff = data[state] - mean[state];
			stddev[state] += diff * diff;
		});

		stddev[col_state] /= float_n;
		stddev[col_state] = SQRT_FUN(stddev[col_state]);
		stddev[col_state] = stddev[col_state] <= eps ? SCALAR_VAL(1.0) : stddev[col_state];
	});

