	// Calculate the M x M correlation matrix:
	//   for i in [0, M-2]:
	//     corr[i][i] = 1
	//     for j in [i+1, M-1]:
	//       corr[i][j] = sum_k data[k][i] * data[k][j]
	//       corr[j][i] = corr[i][j]
	//   corr[M-1][M-1] = 1
	//
	// Implemented via a full (p,q) traversal, doing work only when q >= p.
	// --------------------------------------------------------------------
