constexpr auto p_vec = noarr::vector<'p'>(); // correlation row index
constexpr auto q_vec = noarr::vector<'q'>(); // correlation column index

struct tuning {
	// data: n x m  (rows: samples, cols: variables)
	DEFINE_PROTO_STRUCT(data_layout, m_vec ^ n_vec);

	// corr: p x q (both range over variables, m)
	DEFINE_PROTO_STRUCT(corr_layout, q_vec ^ p_vec);

	// mean: m
	DEFINE_PROTO_STRUCT(mean_layout, m_vec);

	// stddev: m
	DEFINE_PROTO_STRUCT(stddev_layout, m_vec);
} tuning;

// initialization function
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// float_n = (DATA_TYPE)N  (N == number of samples)
	auto n_len = data | get_length<'n'>();
	auto m_len = data | get_length<'m'>();

	float_n = (num_t)n_len;

	traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);
		data[state] = (num_t)(i * j) / (num_t)m_len + (num_t)i;
	});
}

