	// corr:  j x k  (M x M)
	// mean:  j
	// stddev: j
	using namespace noarr;

	num_t eps = SCALAR_VAL(0.1);

	#pragma scop
	// ------------------------------------------------------------------
	// mean[j] = (1 / float_n) * sum_i data[i][j]
	// ------------------------------------------------------------------
	traverser(mean, data).template for_dims<'j'>([=](auto trav_j) {
		// current variable index j is fixed in trav_j
		mean[trav_j] = SCALAR_VAL(0.0);

		// sum over all observations i
		trav_j.template for_each<'i'>([=](auto state) {
			mean[trav_j] += data[state];
		});

		mean[trav_j] /= float_n;
	});

	// ------------------------------------------------------------------
	// stddev[j] = sqrt( (1 / float_n) * sum_i (data[i][j] - mean[j])^2 )
	// with protection against near-zero stddev
	// ------------------------------------------------------------------
	traverser(stddev, mean, data).template for_dims<'j'>([=](auto trav_j) {
		stddev[trav_j] = SCALAR_VAL(0.0);

		trav_j.template for_each<'i'>([=](auto state) {
			num_t diff = data[state] - mean[trav_j];
			stddev[trav_j] += diff * diff;
		});

		stddev[trav_j] /= float_n;
		stddev[trav_j] = SQRT_FUN(stddev[trav_j]);

		// handle near-zero stddev to avoid division by zero later
		stddev[trav_j] = stddev[trav_j] <= eps ? SCALAR_VAL(1.0) : stddev[trav_j];
	});

	// ------------------------------------------------------------------
	// Center and reduce the column vectors:
	//   data[i][j] -= mean[j];
	//   data[i][j] /= sqrt(float_n) * stddev[j];
	// ------------------------------------------------------------------
	num_t sqrt_float_n = SQRT_FUN(float_n);

	traverser(data, mean, stddev).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed (one observation), iterate all variables j
		trav_i.template for_each<'j'>([=](auto state) {
			data[state] -= mean[state]; // mean depends only on 'j'
			data[state] /= sqrt_float_n * stddev[state]; // stddev depends only on 'j'
		});
	});

