	// Calculate the M x M correlation matrix:
	//   for i = 0..M-2:
	//     corr[i][i] = 1;
	//     for j = i+1..M-1:
	//       corr[i][j] = sum_k data[k][i] * data[k][j];
	//       corr[j][i] = corr[i][j];
	//   corr[M-1][M-1] = 1;
	// Here:
	//   - first index i is dimension 'j'
	//   - second index j is dimension 'k'
	//   - sum index k is dimension 'i' of data
	// ------------------------------------------------------------------
	auto m_len = corr | get_length<'j'>(); // M

	traverser(corr, data).template for_dims<'j'>([=](auto trav_row) {
