		auto row_state = trav_row.state();
		std::size_t i_idx = get_index<'j'>(row_state); // i in the original code

		if (i_idx < m_len - 1) {
			// corr[i][i] = 1.0;
			corr[noarr::idx<'j', 'k'>(i_idx, i_idx)] = SCALAR_VAL(1.0);

			// Now iterate j from i+1 to M-1 along dimension 'k'
			auto upper_trav = trav_row.order(
				noarr::slice<'k'>(i_idx + 1, m_len - (i_idx + 1))
			);

			upper_trav.template for_dims<'k'>([=](auto trav_pair) {
				// trav_pair has both 'j' (i_idx) and 'k' (j_idx) fixed
				// Initialize corr[i][j] = 0.0
				corr[trav_pair] = SCALAR_VAL(0.0);

				// Sum over all observations (dimension 'i' of data)
				trav_pair.template for_each<'i'>([=](auto state) {
					// state: ('i' = observation index, 'j' = i_idx, 'k' = j_idx)
					// data[k][i]  -> data[state]           (since 'j' = i_idx)
					// data[k][j]  -> data[ state with 'j' = j_idx ]
					auto state_other = state.template with<noarr::index_in<'j'>>(
						noarr::get_index<'k'>(state)
					);

					corr[trav_pair] += data[state] * data[state_other];
				});

				// corr[j][i] = corr[i][j];
				auto pair_state = trav_pair.state(); // ('j' = i_idx, 'k' = j_idx)
				std::size_t i_idx2 = get_index<'j'>(pair_state);
				std::size_t j_idx2 = get_index<'k'>(pair_state);

				corr[noarr::idx<'j', 'k'>(j_idx2, i_idx2)] = corr[pair_state];
			});
		}
	});

